import OverviewCards from './_components/OverviewCards'
import RevenueChart from './_components/RevenueChart'
import NewProductsChart from './_components/NewProductsChart'
import { auth } from '@/auth'
import { redirect } from 'next/navigation'

export default async function DashboardPage() {
  const session = await auth()

  if (!session?.user && session?.user?.role.toLowerCase() !== 'admin') {
    redirect('/signin')
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <header className="space-y-3">
        <h1 className="text-2xl font-semibold text-[#272727]">Overview</h1>
        <p className="text-[#595959]">Dashboard</p>
      </header>

      {/* Section 1: Overview Cards */}
      <section>
        <OverviewCards />
      </section>

      {/* Section 2 & 3: Revenue & New Products Charts side by side */}
      <div className="flex flex-col lg:flex-row gap-5 items-stretch">
        <section className="flex-1">
          <RevenueChart />
        </section>
        <section className="flex-1">
          <NewProductsChart />
        </section>
      </div>
    </div>
  )
}
